import functools
import gc
import json
from pathlib import Path
import resource
import sys
import threading
import time
sys.path.insert(0, '/home/yo/projects/kza')
import pytest

current = ['collection']
starts = {}
pauses = []
event_stages = []

def observe(phase, info):
    key = (threading.get_ident(), info['generation'])
    if phase == 'start':
        starts[key] = time.perf_counter()
    else:
        begin = starts.pop(key, None)
        if begin is not None:
            elapsed = (time.perf_counter()-begin)*1000
            if elapsed >= 10:
                pauses.append({'node':current[0], 'generation':info['generation'], 'ms':elapsed})

class Probe:
    def pytest_runtest_setup(self, item):
        current[0] = item.nodeid
    def pytest_collection_finish(self, session):
        cls = sys.modules['src.analytics.event_logger'].EventLogger
        for name in ('initialize', '_init_db', 'log'):
            original = getattr(cls,name)
            def wrap(function=original, label=name):
                @functools.wraps(function)
                def measured(*args, **kwargs):
                    begin = time.perf_counter()
                    try:
                        return function(*args, **kwargs)
                    finally:
                        elapsed = (time.perf_counter()-begin)*1000
                        if elapsed >= 10:
                            event_stages.append({'node':current[0], 'stage':label, 'ms':elapsed})
                return measured
            setattr(cls,name,wrap())

gc.callbacks.append(observe)
try:
    code = pytest.main(['tests/','-q','--tb=short','-o','junit_family=xunit1',
                        '--junitxml=/tmp/kza-h3-index-maintenance-reviewed-final.xml'], plugins=[Probe()])
finally:
    gc.callbacks.remove(observe)
    Path('/tmp/kza-h3-index-maintenance-gc-probe.json').write_text(json.dumps({
        'gc_enabled':gc.isenabled(), 'gc_thresholds':gc.get_threshold(),
        'pauses_over_10_ms':pauses, 'event_stages_over_10_ms':event_stages,
        'peak_rss_kib':resource.getrusage(resource.RUSAGE_SELF).ru_maxrss}, indent=2)+'\n')
sys.exit(code)
